package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalGroupedRounds.Round;
import org.kanger.ContextUniversalGroupedRounds.Result;
import org.kanger.ContextUniversalGroupedRounds.Status;
import org.kanger.ContextWitnessResultTransport.*;

/** Independent stable supplied-cut chain replay, without controller execution or admission authority. */
final class ContextUniversalGroupedChainAudit {
    static final class Receipt {
        final Snapshot x;final List<Snapshot> foreign;final Packet input;final Map<Cut,PrivatePool> pools;
        final ContextUniversalSignedUnitExchange.Exchange units;
        final ContextUniversalCompoundExchange.Exchange compounds;
        final ContextUniversalFrozenBranch.Limits limits;final ContextUniversalGroupedLocalRounds.Limits local;
        final int maximumRounds;final Result trace;
        private Receipt(Snapshot x,List<Snapshot> foreign,Packet input,Map<Cut,PrivatePool> pools,ContextUniversalSignedUnitExchange.Exchange units,ContextUniversalCompoundExchange.Exchange compounds,ContextUniversalFrozenBranch.Limits limits,ContextUniversalGroupedLocalRounds.Limits local,int maximumRounds,Result trace){this.x=x;this.foreign=Collections.unmodifiableList(new ArrayList<>(foreign));this.input=input;this.pools=Collections.unmodifiableMap(new LinkedHashMap<>(pools));this.units=units;this.compounds=compounds;this.limits=limits;this.local=local;this.maximumRounds=maximumRounds;this.trace=trace;}
    }
    static final class Inspection {
        final boolean audited;final String phase,reason;final Receipt output;
        private Inspection(boolean audited,String phase,String reason,Receipt output){this.audited=audited;this.phase=phase;this.reason=reason;this.output=output;}
    }
    private static void require(boolean b,String why){if(!b)throw new IllegalStateException(why);}
    private static void unmarked(Packet p){require(p!=null&&p.basis==null&&p.producers.isEmpty()&&!p.observedStep&&p.emptyCut==null&&p.coveredCut==null&&p.roundCut==null&&p.privateTarget==null&&p.emptyTarget==null,"Chain result must not carry coverage/STEP stamps");}
    private static boolean same(Packet a,Packet b,int work){return ContextWitnessResultTransport.sameContents(a,b,work);}
    private static void bounded(Packet p,int depth,Runnable work){unmarked(p);for(Item item:p.items)for(org.kanger.ContextProductionCapture.Support s:item.proofs){work.run();require(s.depth<=depth,"Chain product exceeds fact policy");}}
    private static void products(ContextUniversalSignedProductAudit.Result a,ContextUniversalSignedProductAudit.Result b,Runnable work){
        require(a!=null&&a.bound&&b.bound&&a.coverage==b.coverage&&a.transfer==b.transfer&&a.symbolic==b.symbolic&&a.foreignOnly==b.foreignOnly&&a.products.size()==b.products.size(),"Different actual product audit/inventory");
        for(int i=0;i<a.products.size();++i){work.run();ContextUniversalSignedProductAudit.Product p=a.products.get(i),q=b.products.get(i);require(p!=null&&p.fact.equivalent(q.fact,work)&&p.expected==q.expected&&p.input==q.input&&p.theorem==q.theorem&&p.local==q.local&&p.shared==q.shared&&p.localProof==q.localProof&&p.sharedProof==q.sharedProof,"Different actual bidirectional product evidence");}
    }
    private static boolean declarations(List<ContextProductionInputs.Declaration> a,List<ContextProductionInputs.Declaration> b,Runnable work){if(a.size()!=b.size())return false;for(int i=0;i<a.size();++i){work.run();ContextProductionInputs.Declaration p=a.get(i),q=b.get(i);if(p==null||q==null||!p.source.equals(q.source)||!p.statement.equals(q.statement))return false;}return true;}
    static Inspection inspect(Snapshot x,List<Snapshot> foreign,Packet input,Map<Cut,PrivatePool> pools,ContextUniversalSignedUnitExchange.Exchange units,ContextUniversalCompoundExchange.Exchange compounds,ContextUniversalFrozenBranch.Limits limits,ContextUniversalGroupedLocalRounds.Limits local,int maximumRounds,Result trace,int maximumWork){
        if(maximumWork<1)throw new IllegalArgumentException("Bounded chain verification required");
        String phase="topology";Runnable work=ContextGroundProductionRounds.budget(maximumWork);
        try {
            require(x!=null&&foreign!=null&&foreign.size()<=15&&input!=null&&pools!=null&&compounds!=null&&limits!=null&&local!=null&&maximumRounds>=1&&maximumRounds<=64,"Actual bounded initial chain frame required");
            foreign=new ArrayList<>(foreign);pools=new LinkedHashMap<>(pools);
            require(trace!=null&&trace.status==Status.STABLE_GROUPED_POOLS&&trace.input==input&&trace.output!=null&&trace.symbolicOutput!=null&&trace.compoundOutput!=null&&trace.refutations.isEmpty()&&!trace.history.isEmpty()&&trace.history.size()==trace.completedRounds&&trace.history.size()<=maximumRounds&&trace.phase.equals("stable-grouped-pools"),"Only a complete stable chain can receive stability evidence");
            require(local.kernelRounds==limits.rounds&&local.depth==limits.proofDepth&&local.clauses==limits.clauses&&local.alternatives==limits.alternatives,"Different expected local/kernel policy");
            Map<Cut,Snapshot> targets=new LinkedHashMap<>();targets.put(Cut.of(x),null);for(Snapshot f:foreign){work.run();require(f!=null&&!targets.containsKey(Cut.of(f)),"Repeated/absent supplied chain cut");targets.put(Cut.of(f),f);}List<Cut> cuts=new ArrayList<>(targets.keySet());
            require(compounds.x==x&&compounds.common==input&&compounds.checks.keySet().equals(targets.keySet()),"Different actual initial compound frame");
            if(units!=null)require(units.x==x&&units.common==input&&units.checks.equals(compounds.checks)&&units.barrier==compounds.barrier,"Different actual initial carrier ledger/barrier");
            for(Map.Entry<Cut,PrivatePool> e:pools.entrySet()){work.run();PrivatePool p=e.getValue();require(p!=null&&targets.containsKey(e.getKey())&&!e.getKey().localX&&p.cut.equals(e.getKey())&&p.common==input&&p.x==x&&p.snapshot==targets.get(e.getKey()),"Different actual initial private pool");}
            Packet before=input;Map<Cut,PrivatePool> privateBefore=pools;ContextUniversalSignedUnitExchange.Exchange unitBefore=units;ContextUniversalCompoundExchange.Exchange compoundBefore=compounds;
            // Scan the ENTIRE chain topology before expensive proof replay; allocation equality is not frame identity.
            for(int i=0;i<trace.history.size();++i){
                work.run();Round r=trace.history.get(i);require(r!=null&&r.number==i+1&&r.input==before&&r.privateInput.equals(privateBefore)&&r.symbolicInput==unitBefore&&r.compoundInput==compoundBefore,"Broken actual round input/order chain");
                require(r.checks.keySet().equals(targets.keySet())&&r.certificates.keySet().equals(targets.keySet())&&r.products.keySet().equals(targets.keySet())&&r.barrier!=null&&r.barrier.merged&&r.barrier.branches.keySet().equals(targets.keySet())&&r.barrier.privatePools.keySet().equals(pools.keySet()),"Incomplete all-cut chain inventory");
                for(Cut cut:cuts){work.run();ContextUniversalGroupedLocalRounds.Certificate c=r.certificates.get(cut);ConstraintTransfer t=r.barrier.branches.get(cut);ContextUniversalSignedProductAudit.Result p=r.products.get(cut);require(c!=null&&c.limits==local&&c.output==r.checks.get(cut)&&c.initial.common==before&&c.initial.pool==privateBefore.get(cut)&&c.initial.exchange==unitBefore&&c.initial.compounds==compoundBefore&&c.initial.input.x==x&&c.initial.input.foreign==targets.get(cut)&&c.initial.input.target.equals(cut),"Different actual local certificate/frame/policy");require(t!=null&&t.transferred&&t.certificate==c&&t.proof==c.output&&t.before==before&&t.privateBefore==privateBefore.get(cut)&&p!=null&&p.bound&&p.coverage==c.output&&p.transfer==t&&!c.output.xRefuted&&!c.output.foreignRefuted,"Different actual cut certificate/product/transfer binding");if(t.privateBefore!=null)require(t.privateAfter!=null&&t.privateAfter.sources.equals(pools.get(cut).sources)&&declarations(t.privateAfter.declarations,pools.get(cut).declarations,work),"Private branch metadata differs from original native pool inventory");}
                require(r.symbolicOutput!=null&&r.compoundOutput!=null&&r.symbolicOutput.barrier==r.barrier&&r.compoundOutput.barrier==r.barrier&&r.symbolicOutput.common==r.barrier.packet&&r.compoundOutput.common==r.barrier.packet&&r.symbolicOutput.checks.equals(r.checks)&&r.compoundOutput.checks.equals(r.checks)&&r.symbolicOutput.prior!=null&&r.compoundOutput.prior!=null&&r.symbolicOutput.prior.common==before&&r.compoundOutput.prior.common==before,"Different actual collection/rebase barrier/checks");
                boolean changed=r.commonChanged||r.privateChanged||r.symbolicChanged||r.compoundChanged||r.barrier.localChanged;require(i==trace.history.size()-1?!changed:changed,"Premature stability or ignored earlier stable round");
                before=r.barrier.packet;privateBefore=r.barrier.privatePools;unitBefore=r.symbolicOutput;compoundBefore=r.compoundOutput;
            }
            Round last=trace.history.get(trace.history.size()-1);require(trace.output==last.barrier&&trace.symbolicOutput==last.symbolicOutput&&trace.compoundOutput==last.compoundOutput,"Final output is not the actual terminal barrier");
            phase="initial-frame";ContextProductionFamilyAssembly.identity(x,true,work);for(Snapshot f:foreign){work.run();ContextProductionFamilyAssembly.identity(f,false,work);ContextProductionFamilyAssembly.disjoint(x,f,work);}ContextWitnessResultTransport.family(input,cuts,maximumWork);ContextUniversalCompoundExchange.check(compounds,x,input,limits.proofDepth,work);for(Cut cut:cuts){work.run();require(compounds.checks.get(cut).input.foreign==targets.get(cut),"Different initial actual snapshot");}if(units!=null)ContextUniversalSignedUnitExchange.check(units,x,input,limits.proofDepth,work);
            for(PrivatePool p:pools.values()){work.run();PrivatePool seeds=ContextWitnessResultTransport.privatePoolSigned(input,x,p.snapshot,maximumWork);require(p.sources.equals(seeds.sources)&&declarations(p.declarations,seeds.declarations,work)&&ContextWitnessResultTransport.retains(seeds.local,p.local,work),"Initial private metadata/seeds differ from actual whole native snapshots");}
            for(Round r:trace.history){
                phase="local-replay";ContextUniversalGroupedRounds.checkCertificates(x,targets,r.input,r.privateInput,r.symbolicInput,r.compoundInput,r.checks,r.certificates,local,work);
                for(Cut cut:cuts){work.run();ContextUniversalGroupedLocalRounds.Certificate c=r.certificates.get(cut);ContextUniversalFrozenConstraints.Result initial=c.initial;ContextUniversalFrozenConstraints.Result replay=ContextUniversalFrozenConstraints.closeSignedCompounds(initial.input,r.input,r.privateInput.get(cut),r.symbolicInput,r.compoundInput,limits.rounds,limits.proofDepth,limits.clauses,limits.alternatives,limits.work);require(replay.closed&&ContextUniversalGroupedLocalRounds.sameContents(initial,replay,work),"Initial ordinary receiver differs from bounded independent replay");}
                phase="product-replay";boolean localChanged=false;
                for(Cut cut:cuts){work.run();ConstraintTransfer t=r.barrier.branches.get(cut);ContextUniversalSignedProductAudit.Result replay=ContextUniversalSignedProductAudit.bind(r.checks.get(cut),t,65536,limits.work);require(replay.bound,replay.reason);products(r.products.get(cut),replay,work);bounded(t.output,limits.factDepth,work);bounded(t.local,limits.factDepth,work);boolean lc=!same(t.privateBefore==null?r.input:t.privateBefore.local,t.local,maximumWork),cc=!same(r.input,t.output,maximumWork);require(t.localChanged==lc&&t.commonChanged==cc,"Forged transfer change flags");localChanged|=lc;}
                phase="fixed-private-replay";ConstraintBarrier merged=ContextWitnessResultTransport.mergeConstraints(ContextWitnessResultTransport.family(r.input,cuts,maximumWork),r.barrier.branches,maximumWork);require(merged.merged&&same(merged.packet,r.barrier.packet,maximumWork)&&r.barrier.changed==merged.changed&&r.barrier.localChanged==localChanged&&merged.localChanged==localChanged,"Different independently merged fixed barrier/minima/flags");bounded(r.barrier.packet,limits.factDepth,work);boolean privateChanged=false;
                for(Cut cut:pools.keySet()){work.run();PrivatePool actual=r.barrier.privatePools.get(cut),expected=merged.privatePools.get(cut),prior=r.privateInput.get(cut);require(actual!=null&&expected!=null&&actual.common==r.barrier.packet&&actual.x==x&&actual.snapshot==targets.get(cut)&&actual.cut.equals(cut)&&actual.sources.equals(expected.sources)&&actual.sources.equals(pools.get(cut).sources)&&declarations(actual.declarations,expected.declarations,work)&&declarations(actual.declarations,pools.get(cut).declarations,work)&&same(actual.local,expected.local,maximumWork),"Different independent private rebase/minima");unmarked(actual.local);privateChanged|=!same(prior.local,actual.local,maximumWork);}
                phase="carrier-replay";ContextUniversalSignedUnitExchange.Collection collected=ContextUniversalSignedUnitExchange.collect(x,r.input,cuts,r.checks,limits.clauses,limits.alternatives,limits.factDepth,limits.work);require(collected.collected&&ContextUniversalSignedUnitExchange.sameContents(collected.output,r.symbolicOutput,maximumWork),"Different bounded symbolic collection/minima");require(r.compoundOutput.maximumClauses==limits.clauses&&r.compoundOutput.maximumAlternatives==limits.alternatives&&r.compoundOutput.maximumDepth==limits.factDepth,"Different carrier enumeration policy");ContextUniversalSignedUnitExchange.check(r.symbolicOutput,x,r.barrier.packet,limits.factDepth,work);ContextUniversalCompoundExchange.check(r.compoundOutput,x,r.barrier.packet,limits.factDepth,work);
                phase="stability-replay";require(r.commonChanged==!same(r.input,r.barrier.packet,maximumWork)&&r.commonChanged==r.barrier.changed&&r.privateChanged==privateChanged&&r.symbolicChanged==!ContextUniversalSignedUnitExchange.sameContents(r.symbolicInput,r.symbolicOutput,maximumWork)&&r.compoundChanged==!ContextUniversalCompoundExchange.sameContents(r.compoundInput,r.compoundOutput,maximumWork),"Different full typed Source/grade change flags");
            }
            return new Inspection(true,"stable-chain","Actual complete supplied-cut chain and four-pool Source/grade stability independently replayed; native/family/admission authority remains open",new Receipt(x,foreign,input,pools,units,compounds,limits,local,maximumRounds,trace));
        }catch(Exception failure){return new Inspection(false,phase,failure.toString(),null);}
    }
    static void check(Receipt receipt,int maximumWork){require(receipt!=null,"Actual chain receipt required");Inspection checked=inspect(receipt.x,receipt.foreign,receipt.input,receipt.pools,receipt.units,receipt.compounds,receipt.limits,receipt.local,receipt.maximumRounds,receipt.trace,maximumWork);require(checked.audited,checked.phase+": "+checked.reason);}
}
